  // Stagger delays
  const delay1 = 15; // 0.5s
  const delay2 = 45; // 1.5s
  const delay3 = 75; // 2.5s

  // Bubble positions relative to mouth (percentages)
  // Bubble 1: Top Right
  const b1OffsetX = 15;
